--
-- Name: fn_calcular_coste_receta(uuid); Type: FUNCTION; Schema: public; Owner: adrianmartinlopez
--

CREATE FUNCTION public.fn_calcular_coste_receta(p_producto_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_tipo_producto TEXT;
  v_tipo_receta TEXT;
  v_receta_id UUID;
  v_rendimiento NUMERIC(20,6);
  v_coste_total NUMERIC(20,6) := 0;
BEGIN
  -- Tipo del producto → determina qué receta buscar
  SELECT tipo::text INTO v_tipo_producto
  FROM public.productos WHERE id = p_producto_id;

  v_tipo_receta := CASE
    WHEN v_tipo_producto = 'producto_envasado'  THEN 'envasado'
    WHEN v_tipo_producto = 'producto_fabricado' THEN 'fabricacion'
    ELSE NULL
  END;

  IF v_tipo_receta IS NULL THEN RETURN NULL; END IF;

  -- Receta activa más reciente
  SELECT id, rendimiento INTO v_receta_id, v_rendimiento
  FROM public.recetas
  WHERE producto_id = p_producto_id
    AND tipo_receta = v_tipo_receta
    AND activa = TRUE
  ORDER BY version DESC
  LIMIT 1;

  IF v_receta_id IS NULL OR v_rendimiento IS NULL OR v_rendimiento <= 0 THEN
    RETURN NULL;
  END IF;

  -- Suma del coste de cada ingrediente:
  --   cantidad × (1 + merma%) × CMP_o_precio
  -- CMP del ingrediente = COALESCE(coste_medio_actual, precio_unitario, 0)
  SELECT COALESCE(SUM(
    ir.cantidad
    * (1 + ir.porcentaje_merma::NUMERIC / 100)
    * COALESCE(NULLIF(ip.coste_medio_actual, 0), ip.precio_unitario, 0)
  ), 0)
  INTO v_coste_total
  FROM public.ingredientes_receta ir
  JOIN public.productos ip ON ip.id = ir.materia_prima_id
  WHERE ir.receta_id = v_receta_id;

  IF v_coste_total <= 0 THEN RETURN NULL; END IF;

  RETURN (v_coste_total / v_rendimiento)::NUMERIC(20,6);
END
$$;


ALTER FUNCTION public.fn_calcular_coste_receta(p_producto_id uuid) OWNER TO adrianmartinlopez;

--
-- Name: fn_calcular_coste_receta_futuro(uuid, integer); Type: FUNCTION; Schema: public; Owner: loga
--

CREATE FUNCTION public.fn_calcular_coste_receta_futuro(p_producto_id uuid, p_depth integer DEFAULT 0) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_tipo TEXT;
  v_tipo_receta TEXT;
  v_receta_id UUID;
  v_rendimiento NUMERIC(20,6);
  v_coste_total NUMERIC(20,6) := 0;
  v_ing RECORD;
  v_precio_ing NUMERIC(20,6);
BEGIN
  -- Protección contra recursión patológica (debería bloquear 027 antes,
  -- pero por seguridad).
  IF p_depth > 20 THEN RETURN 0; END IF;

  SELECT tipo::text INTO v_tipo
  FROM public.productos WHERE id = p_producto_id;

  v_tipo_receta := CASE
    WHEN v_tipo = 'producto_envasado'  THEN 'envasado'
    WHEN v_tipo = 'producto_fabricado' THEN 'fabricacion'
    ELSE NULL
  END;

  -- Hoja: MP, embalaje, terminado-sin-receta → precio ficha
  IF v_tipo_receta IS NULL THEN
    SELECT COALESCE(precio_unitario, 0) INTO v_precio_ing
    FROM public.productos WHERE id = p_producto_id;
    RETURN COALESCE(v_precio_ing, 0);
  END IF;

  -- Receta activa
  SELECT id, rendimiento INTO v_receta_id, v_rendimiento
  FROM public.recetas
  WHERE producto_id = p_producto_id
    AND tipo_receta = v_tipo_receta
    AND activa = TRUE
  ORDER BY version DESC LIMIT 1;

  -- Sin receta válida: caer al precio almacenado (lo mejor que tenemos)
  IF v_receta_id IS NULL OR v_rendimiento IS NULL OR v_rendimiento <= 0 THEN
    SELECT COALESCE(precio_unitario, 0) INTO v_precio_ing
    FROM public.productos WHERE id = p_producto_id;
    RETURN COALESCE(v_precio_ing, 0);
  END IF;

  -- Sumar coste recursivo de cada ingrediente
  FOR v_ing IN
    SELECT ir.cantidad, ir.porcentaje_merma, ir.materia_prima_id
    FROM public.ingredientes_receta ir
    WHERE ir.receta_id = v_receta_id
  LOOP
    v_precio_ing := public.fn_calcular_coste_receta_futuro(
      v_ing.materia_prima_id, p_depth + 1
    );
    v_coste_total := v_coste_total
      + v_ing.cantidad
      * (1 + COALESCE(v_ing.porcentaje_merma, 0)::NUMERIC / 100)
      * COALESCE(v_precio_ing, 0);
  END LOOP;

  IF v_coste_total <= 0 THEN RETURN 0; END IF;
  RETURN (v_coste_total / v_rendimiento)::NUMERIC(20,6);
END
$$;


ALTER FUNCTION public.fn_calcular_coste_receta_futuro(p_producto_id uuid, p_depth integer) OWNER TO loga;

--
-- Name: fn_check_alerta_stock(); Type: FUNCTION; Schema: public; Owner: loga
--

CREATE FUNCTION public.fn_check_alerta_stock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_producto RECORD;
  v_umbral NUMERIC;
  v_porcentaje NUMERIC;
BEGIN
  SELECT p.*, cg.porcentaje_alerta
  INTO v_producto
  FROM productos p, configuracion_global cg
  WHERE p.id = NEW.producto_id AND cg.id = 1;

  IF v_producto IS NULL THEN RETURN NEW; END IF;

  v_porcentaje := COALESCE(v_producto.porcentaje_alerta, 20);
  v_umbral := v_producto.stock_minimo * (1 + v_porcentaje / 100.0);

  IF v_producto.stock_actual <= v_umbral AND v_producto.stock_minimo > 0 THEN
    VALUES (
      'alerta_stock',
      'Stock bajo: ' || v_producto.nombre,
      v_producto.nombre || ' tiene ' || ROUND(v_producto.stock_actual::NUMERIC, 2) || ' ' || v_producto.unidad_medida ||
      ' (minimo: ' || ROUND(v_producto.stock_minimo::NUMERIC, 2) || ')',
      v_producto.id
    )
    ON CONFLICT (producto_id, tipo) WHERE leida = FALSE DO UPDATE SET
      created_at = NOW(),
      mensaje = EXCLUDED.mensaje;
  ELSE
    -- Limpiar notificacion si stock vuelve a niveles normales
    UPDATE notificaciones SET leida = TRUE
    WHERE producto_id = NEW.producto_id AND tipo = 'alerta_stock' AND leida = FALSE;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_check_alerta_stock() OWNER TO loga;

--
-- Name: fn_check_ciclo_receta(); Type: FUNCTION; Schema: public; Owner: adrianmartinlopez
--

CREATE FUNCTION public.fn_check_ciclo_receta() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_producto_final UUID;
  v_ciclo_detectado BOOLEAN;
BEGIN
  -- Producto final de la receta a la que pertenece este ingrediente
  SELECT producto_id INTO v_producto_final
  FROM public.recetas WHERE id = NEW.receta_id;

  -- Ciclo directo: el ingrediente es el propio producto final
  IF NEW.materia_prima_id = v_producto_final THEN
    RAISE EXCEPTION 'Ciclo en receta: un producto no puede ser ingrediente de su propia receta'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Ciclo indirecto: recorrer el grafo desde el ingrediente hacia
  -- abajo. Si en algún nivel encontramos el producto final, hay ciclo.
  WITH RECURSIVE descendientes AS (
    -- Nivel 0: el ingrediente que se quiere añadir
    SELECT NEW.materia_prima_id AS producto_id, 0 AS depth
    UNION ALL
    -- Niveles siguientes: los ingredientes de las recetas activas
    -- de cada producto descendiente
    SELECT ir.materia_prima_id, d.depth + 1
    FROM descendientes d
    JOIN public.recetas r ON r.producto_id = d.producto_id AND r.activa = TRUE
    JOIN public.ingredientes_receta ir ON ir.receta_id = r.id
    WHERE d.depth < 20
  )
  SELECT EXISTS(
    SELECT 1 FROM descendientes WHERE producto_id = v_producto_final
  ) INTO v_ciclo_detectado;

  IF v_ciclo_detectado THEN
    RAISE EXCEPTION 'Ciclo en receta: añadir este ingrediente crearía una dependencia circular con el producto final'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_check_ciclo_receta() OWNER TO adrianmartinlopez;

--
-- Name: fn_numero_oc(); Type: FUNCTION; Schema: public; Owner: adrianmartinlopez
--

CREATE FUNCTION public.fn_numero_oc() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_intento INT := 0;
  v_max     INT;
  v_year    TEXT;
BEGIN
  IF NEW.numero_oc IS NOT NULL AND NEW.numero_oc <> '' THEN
    RETURN NEW;
  END IF;

  v_year := TO_CHAR(NOW(), 'YYYY');
  NEW.numero_oc := 'OC-' || v_year || '-' ||
    LPAD(nextval('public.seq_numero_oc')::TEXT, 5, '0');

  WHILE v_intento < 5 AND EXISTS (
    SELECT 1 FROM public.ordenes_compra WHERE numero_oc = NEW.numero_oc
  ) LOOP
    v_intento := v_intento + 1;
    SELECT COALESCE(MAX(CAST(SUBSTRING(numero_oc FROM '[0-9]+$') AS INT)), 0)
      INTO v_max FROM public.ordenes_compra;
    PERFORM setval('public.seq_numero_oc', v_max, TRUE);
    NEW.numero_oc := 'OC-' || v_year || '-' ||
      LPAD(nextval('public.seq_numero_oc')::TEXT, 5, '0');
    RAISE WARNING '[fn_numero_oc] secuencia desincronizada — re-sync intento %, nuevo numero=%',
      v_intento, NEW.numero_oc;
  END LOOP;

  RETURN NEW;
END
$_$;


