--
-- Name: fn_recalcular_cmp(); Type: FUNCTION; Schema: public; Owner: loga
--

CREATE FUNCTION public.fn_recalcular_cmp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE productos SET
    coste_medio_actual = COALESCE((
      SELECT CASE WHEN SUM(cantidad_actual) > 0
        THEN SUM(cantidad_actual * COALESCE(precio_compra, precio_unitario)) / SUM(cantidad_actual)
        ELSE precio_unitario
      END
      FROM lotes WHERE producto_id = NEW.producto_id AND estado = 'aprobado' AND cantidad_actual > 0
    ), precio_unitario),
    version = version + 1
  WHERE id = NEW.producto_id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_recalcular_cmp() OWNER TO loga;

--
-- Name: fn_recalcular_cmp(uuid); Type: FUNCTION; Schema: public; Owner: adrianmartinlopez
--

CREATE FUNCTION public.fn_recalcular_cmp(p_producto_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cmp NUMERIC(20,6);
  v_total_cant NUMERIC(20,6);
  v_total_valor NUMERIC(20,6);
BEGIN
  SELECT
    COALESCE(SUM(precio_compra * cantidad_actual), 0),
    COALESCE(SUM(cantidad_actual), 0)
  INTO v_total_valor, v_total_cant
  FROM public.lotes
  WHERE producto_id = p_producto_id
    AND estado = 'aprobado'
    AND cantidad_actual > 0;

  IF v_total_cant > 0 THEN
    v_cmp := v_total_valor / v_total_cant;
  ELSE
    -- Sin lotes con stock: preservar último CMP conocido (no resetear a 0
    -- para no perder referencia de coste cuando el producto se agota
    -- temporalmente). Si nunca hubo lotes, queda lo que estuviese.
    RETURN;
  END IF;

  UPDATE public.productos
  SET coste_medio_actual = v_cmp,
      updated_at = NOW()
  WHERE id = p_producto_id
    AND COALESCE(coste_medio_actual, 0) <> v_cmp; -- evitar UPDATE si no cambia
END
$$;


ALTER FUNCTION public.fn_recalcular_cmp(p_producto_id uuid) OWNER TO adrianmartinlopez;

--
-- Name: fn_recalcular_stock_actual(uuid); Type: FUNCTION; Schema: public; Owner: adrianmartinlopez
--

CREATE FUNCTION public.fn_recalcular_stock_actual(p_producto_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_nuevo NUMERIC(20,6);
BEGIN
  v_nuevo := public.fn_stock_disponible(p_producto_id);

  UPDATE public.productos
  SET stock_actual = v_nuevo,
      updated_at = NOW()
  WHERE id = p_producto_id
    AND stock_actual IS DISTINCT FROM v_nuevo; -- evitar UPDATE si no cambia
END
$$;


