-- Name: fn_trg_ingredientes_receta_coste(); Type: FUNCTION; Schema: public; Owner: adrianmartinlopez
--

CREATE FUNCTION public.fn_trg_ingredientes_receta_coste() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_producto_id UUID;
BEGIN
  -- Encontrar producto final de la receta afectada
  SELECT producto_id INTO v_producto_id
  FROM public.recetas
  WHERE id = COALESCE(NEW.receta_id, OLD.receta_id);

  IF v_producto_id IS NOT NULL THEN
    PERFORM public.fn_actualizar_coste_si_no_manual(v_producto_id);
  END IF;

  RETURN COALESCE(NEW, OLD);
END
$$;


ALTER FUNCTION public.fn_trg_ingredientes_receta_coste() OWNER TO adrianmartinlopez;

--
-- Name: fn_trg_lotes_cmp(); Type: FUNCTION; Schema: public; Owner: adrianmartinlopez
--

CREATE FUNCTION public.fn_trg_lotes_cmp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- INSERT: usar NEW
  IF TG_OP = 'INSERT' THEN
    PERFORM public.fn_recalcular_cmp(NEW.producto_id);
    RETURN NEW;
  END IF;

  -- UPDATE: si cambia algo relevante para CMP, recalcular.
  -- Si cambia el producto_id (raro pero posible), recalcular AMBOS.
  IF TG_OP = 'UPDATE' THEN
    IF NEW.producto_id <> OLD.producto_id THEN
      PERFORM public.fn_recalcular_cmp(OLD.producto_id);
      PERFORM public.fn_recalcular_cmp(NEW.producto_id);
    ELSIF NEW.cantidad_actual IS DISTINCT FROM OLD.cantidad_actual
       OR NEW.estado IS DISTINCT FROM OLD.estado
       OR NEW.precio_compra IS DISTINCT FROM OLD.precio_compra THEN
      PERFORM public.fn_recalcular_cmp(NEW.producto_id);
    END IF;
    RETURN NEW;
  END IF;

  -- DELETE: usar OLD
  IF TG_OP = 'DELETE' THEN
    PERFORM public.fn_recalcular_cmp(OLD.producto_id);
    RETURN OLD;
  END IF;

  RETURN NULL;
END
$$;


ALTER FUNCTION public.fn_trg_lotes_cmp() OWNER TO adrianmartinlopez;

--
-- Name: fn_trg_lotes_coste_recursivo(); Type: FUNCTION; Schema: public; Owner: adrianmartinlopez
--

CREATE FUNCTION public.fn_trg_lotes_coste_recursivo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_producto_id UUID;
  v_producto_final UUID;
BEGIN
  v_producto_id := COALESCE(NEW.producto_id, OLD.producto_id);

  -- Encontrar todos los productos cuyas recetas activas usan este
  -- producto como ingrediente, y recalcular su coste.
  FOR v_producto_final IN
    SELECT DISTINCT r.producto_id
    FROM public.recetas r
    JOIN public.ingredientes_receta ir ON ir.receta_id = r.id
    WHERE ir.materia_prima_id = v_producto_id
      AND r.activa = TRUE
  LOOP
    PERFORM public.fn_actualizar_coste_si_no_manual(v_producto_final);
  END LOOP;

  RETURN COALESCE(NEW, OLD);
END
$$;


ALTER FUNCTION public.fn_trg_lotes_coste_recursivo() OWNER TO adrianmartinlopez;

--
-- Name: fn_trg_lotes_stock_actual(); Type: FUNCTION; Schema: public; Owner: adrianmartinlopez
--

CREATE FUNCTION public.fn_trg_lotes_stock_actual() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.fn_recalcular_stock_actual(NEW.producto_id);
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.producto_id <> OLD.producto_id THEN
      PERFORM public.fn_recalcular_stock_actual(OLD.producto_id);
      PERFORM public.fn_recalcular_stock_actual(NEW.producto_id);
    ELSIF NEW.cantidad_actual IS DISTINCT FROM OLD.cantidad_actual
       OR NEW.estado IS DISTINCT FROM OLD.estado THEN
      PERFORM public.fn_recalcular_stock_actual(NEW.producto_id);
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    PERFORM public.fn_recalcular_stock_actual(OLD.producto_id);
    RETURN OLD;
  END IF;

  RETURN NULL;
END
$$;


ALTER FUNCTION public.fn_trg_lotes_stock_actual() OWNER TO adrianmartinlopez;

--
-- Name: fn_trg_recetas_coste(); Type: FUNCTION; Schema: public; Owner: adrianmartinlopez
--

CREATE FUNCTION public.fn_trg_recetas_coste() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.fn_actualizar_coste_si_no_manual(NEW.producto_id);
  ELSIF TG_OP = 'UPDATE' THEN
    -- Solo recalcular si cambió algo relevante
    IF NEW.rendimiento IS DISTINCT FROM OLD.rendimiento
       OR NEW.activa IS DISTINCT FROM OLD.activa
       OR NEW.tipo_receta IS DISTINCT FROM OLD.tipo_receta THEN
      PERFORM public.fn_actualizar_coste_si_no_manual(NEW.producto_id);
      IF NEW.producto_id <> OLD.producto_id THEN
        PERFORM public.fn_actualizar_coste_si_no_manual(OLD.producto_id);
      END IF;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    PERFORM public.fn_actualizar_coste_si_no_manual(OLD.producto_id);
  END IF;
  RETURN COALESCE(NEW, OLD);
END
$$;


ALTER FUNCTION public.fn_trg_recetas_coste() OWNER TO adrianmartinlopez;

