    CONSTRAINT pedidos_proveedor_estado_check CHECK (((estado)::text = ANY (ARRAY[('borrador'::character varying)::text, ('enviado'::character varying)::text, ('pendiente'::character varying)::text, ('completado'::character varying)::text, ('cancelado'::character varying)::text]))),
    CONSTRAINT pedidos_proveedor_origen_check CHECK (((origen)::text = ANY (ARRAY[('manual'::character varying)::text, ('automatizacion'::character varying)::text])))
);


ALTER TABLE public.pedidos_proveedor OWNER TO loga;

--
-- Name: productos; Type: TABLE; Schema: public; Owner: loga
--

CREATE TABLE public.productos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo character varying(50) NOT NULL,
    nombre character varying(255) NOT NULL,
    descripcion text,
    tipo public.tipo_producto DEFAULT 'materia_prima'::public.tipo_producto NOT NULL,
    unidad_medida character varying(20) DEFAULT 'kg'::character varying NOT NULL,
    stock_actual numeric(20,6) DEFAULT 0 NOT NULL,
    stock_minimo numeric(20,6) DEFAULT 0 NOT NULL,
    stock_maximo numeric(20,6) DEFAULT 0 NOT NULL,
    precio_unitario numeric(20,6) DEFAULT 0 NOT NULL,
    proveedor_id uuid,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    precio_venta numeric(20,6) DEFAULT 0,
    subtipo character varying(20) DEFAULT NULL::character varying,
    granel_id uuid,
    caducidad_meses integer,
    peso_unitario_kg numeric(10,4) DEFAULT NULL::numeric,
    version integer DEFAULT 1,
    coste_medio_actual numeric(20,6) DEFAULT 0,
    peso_plastico_kg numeric(10,4) DEFAULT 0,
    sds_url text,
    auto_email_proveedor boolean,
    auto_compra_activa boolean,
    auto_fabricacion_activa boolean,
    auto_envasado_activa boolean,
    safety_stock_pct numeric(5,2),
    dias_anticipacion smallint,
    cantidad_promedio_mensual numeric(20,6),
    unidades_por_envase integer,
    precio_coste_manual boolean DEFAULT false NOT NULL,
    CONSTRAINT productos_dias_anticipacion_check CHECK (((dias_anticipacion IS NULL) OR ((dias_anticipacion >= 0) AND (dias_anticipacion <= 30)))),
    CONSTRAINT productos_precio_unitario_check CHECK ((precio_unitario >= (0)::numeric)),
    CONSTRAINT productos_safety_stock_pct_check CHECK (((safety_stock_pct IS NULL) OR ((safety_stock_pct >= (0)::numeric) AND (safety_stock_pct <= (200)::numeric)))),
    CONSTRAINT productos_stock_actual_check CHECK ((stock_actual >= (0)::numeric)),
    CONSTRAINT productos_stock_maximo_check CHECK ((stock_maximo >= (0)::numeric)),
    CONSTRAINT productos_stock_minimo_check CHECK ((stock_minimo >= (0)::numeric)),
    CONSTRAINT productos_unidades_por_envase_check CHECK (((unidades_por_envase IS NULL) OR (unidades_por_envase >= 1)))
);


ALTER TABLE public.productos OWNER TO loga;

--
-- Name: COLUMN productos.subtipo; Type: COMMENT; Schema: public; Owner: loga
--

COMMENT ON COLUMN public.productos.subtipo IS 'granel | envasado | null(materia prima/embalaje)';


--
-- Name: COLUMN productos.caducidad_meses; Type: COMMENT; Schema: public; Owner: loga
--

COMMENT ON COLUMN public.productos.caducidad_meses IS 'Meses de caducidad desde entrada. Si está definido, al crear lote se auto-calcula fecha_caducidad';


--
-- Name: COLUMN productos.peso_plastico_kg; Type: COMMENT; Schema: public; Owner: loga
--

COMMENT ON COLUMN public.productos.peso_plastico_kg IS 'Peso del plástico del envase en kg (Ley 7/2022 impuesto envases plástico)';


--
-- Name: COLUMN productos.auto_email_proveedor; Type: COMMENT; Schema: public; Owner: loga
--

COMMENT ON COLUMN public.productos.auto_email_proveedor IS 'Override por producto. NULL = usa default global.';


--
-- Name: COLUMN productos.safety_stock_pct; Type: COMMENT; Schema: public; Owner: loga
--

COMMENT ON COLUMN public.productos.safety_stock_pct IS 'Override % safety stock. NULL = usa default global.';


--
-- Name: COLUMN productos.dias_anticipacion; Type: COMMENT; Schema: public; Owner: loga
--

COMMENT ON COLUMN public.productos.dias_anticipacion IS 'Días entre detección y fecha planificada. NULL = global.';


--
-- Name: COLUMN productos.cantidad_promedio_mensual; Type: COMMENT; Schema: public; Owner: loga
--

COMMENT ON COLUMN public.productos.cantidad_promedio_mensual IS 'Manual override del consumo promedio. NULL = se calcula desde stock_moves últimos 90d.';


--
-- Name: COLUMN productos.unidades_por_envase; Type: COMMENT; Schema: public; Owner: loga
--

COMMENT ON COLUMN public.productos.unidades_por_envase IS 'Multiplicador para envases tipo caja/palé. Si una caja contiene 18 frascos, valor=18. NULL = envase unidad. Solo aplica a tipo=material_embalaje.';


--
-- Name: COLUMN productos.precio_coste_manual; Type: COMMENT; Schema: public; Owner: loga
--

COMMENT ON COLUMN public.productos.precio_coste_manual IS 'Si TRUE, precio_unitario es manual y NO se sobrescribe por el cálculo automático desde receta. Si FALSE (default), el sistema lo recalcula tras cambios en receta o CMP de ingredientes.';


--
-- Name: productos_con_disponible; Type: VIEW; Schema: public; Owner: adrianmartinlopez
--

CREATE VIEW public.productos_con_disponible AS
 SELECT id,
    codigo,
    nombre,
    descripcion,
    tipo,
    unidad_medida,
    stock_actual,
    stock_minimo,
    stock_maximo,
    precio_unitario,
    proveedor_id,
    activo,
    created_at,
    updated_at,
    precio_venta,
    subtipo,
    granel_id,
    caducidad_meses,
    peso_unitario_kg,
    version,
    coste_medio_actual,
    peso_plastico_kg,
    sds_url,
    auto_email_proveedor,
    auto_compra_activa,
    auto_fabricacion_activa,
    auto_envasado_activa,
    safety_stock_pct,
    dias_anticipacion,
    cantidad_promedio_mensual,
    unidades_por_envase,
    public.fn_stock_disponible(id) AS stock_disponible,
    (COALESCE(( SELECT sum(l.cantidad_actual) AS sum
           FROM public.lotes l
          WHERE ((l.producto_id = p.id) AND (l.estado = 'cuarentena'::public.estado_lote) AND (l.cantidad_actual > (0)::numeric))), (0)::numeric))::numeric(20,6) AS stock_en_cuarentena
   FROM public.productos p;


ALTER VIEW public.productos_con_disponible OWNER TO adrianmartinlopez;

